INSERT INTO hit_report_modules (id, category, title, content) VALUES
-- ── R 현실 중심 (15) ──
('RIASEC-RIS','riasec','RIS (현실-탐구-사회)','손으로 직접 다루는 일(R)이 중심이고, 원리를 파고드는 탐구(I)와 사람을 돕는 마음(S)이 더해진 조합입니다. 기술을 정확히 이해한 뒤 그 기술로 사람에게 실질적인 도움을 줄 때 보람이 큽니다. 말보다 시범으로 가르치는 편이라 현장 교육에 강하지만, 이론 설명을 길게 해야 하는 자리는 미리 준비해 두면 좋습니다. 추천 직무: 재활·물리치료, 의료기사, 기술 교육 강사, 현장 안전 관리.'),
('RIASEC-RIC','riasec','RIC (현실-탐구-관습)','손으로 다루는 기술(R)이 중심이고, 분석(I)과 체계(C)가 받쳐 주는 조합입니다. 장비와 시스템이 왜 그렇게 움직이는지 이해하고, 정해진 기준대로 정확히 운영하는 데 강합니다. 오차를 줄이는 일에서 만족을 느끼지만, 정답이 없는 모호한 일에서는 답답함을 느낄 수 있습니다. 추천 직무: 품질 관리, 설비·생산 엔지니어, 시험·검사 분석, IT 인프라 운영.'),
('RIASEC-RAI','riasec','RAI (현실-예술-탐구)','실물을 만드는 일(R)이 중심이고, 창의성(A)과 탐구(I)가 더해진 조합입니다. 머릿속 아이디어를 시제품으로 직접 만들어 보고, 왜 되는지 따져 가며 고쳐 나가는 방식을 좋아합니다. 만들면서 생각하는 유형이라 기획서만 쓰는 일보다 손이 가는 일에서 힘이 납니다. 추천 직무: 제품 디자인, 프로토타이핑, 3D·모션 그래픽, 사운드·조명 엔지니어.'),
('RIASEC-RAS','riasec','RAS (현실-예술-사회)','손으로 만드는 일(R)이 중심이고, 창의성(A)과 사람을 향한 관심(S)이 더해진 조합입니다. 직접 만든 것으로 사람들에게 즐거움이나 편안함을 줄 때 보람을 느낍니다. 혼자 작업하는 시간과 사람을 만나는 시간이 균형을 이룰 때 오래 지치지 않습니다. 추천 직무: 공방·체험 프로그램 운영, 공간 연출, 요리·제과, 미술·공예 강사.'),
('RIASEC-RAE','riasec','RAE (현실-예술-기업)','실물을 다루는 일(R)이 중심이고, 창의성(A)과 추진력(E)이 더해진 조합입니다. 만들고 싶은 것이 생기면 직접 손을 대고, 그것을 사업이나 프로젝트로 키우려는 의지도 있습니다. 실행이 빠른 만큼 예산·일정 같은 관리 업무는 체계를 세워 두거나 동료와 나누는 편이 좋습니다. 추천 직무: 영상·사진 프로덕션 운영, 메이커·제조 창업, 공간·인테리어 사업, 촬영 감독.'),
('RIASEC-RSI','riasec','RSI (현실-사회-탐구)','몸으로 하는 일(R)이 중심이고, 사람을 돕는 마음(S)과 탐구(I)가 더해진 조합입니다. 현장에서 사람을 직접 돕고, 그 과정에서 더 나은 방법을 연구합니다. 말보다 행동으로 신뢰를 얻지만, 자기 몸과 시간을 지나치게 쓰지 않도록 경계를 정해 두는 것이 중요합니다. 추천 직무: 응급구조·간호, 운동 처방·트레이너, 재활 치료, 현장 기술 지원.'),
('RIASEC-RSA','riasec','RSA (현실-사회-예술)','실물을 다루는 일(R)이 중심이고, 사람(S)과 표현(A)이 더해진 조합입니다. 직접 만들고 보여 주며 사람들과 함께 무언가를 완성하는 활동을 즐깁니다. 결과물이 눈에 보이고 사람의 반응을 바로 볼 수 있을 때 동기가 커지고, 반응이 늦게 오는 일에서는 중간 목표를 잘게 나누면 좋습니다. 추천 직무: 체험·공예 교육, 무대·행사 연출 스태프, 요리 강사, 원예·조경 치료.'),
('RIASEC-RSE','riasec','RSE (현실-사회-기업)','손으로 하는 일(R)이 중심이고, 사람(S)과 리더십(E)이 더해진 조합입니다. 현장에서 직접 뛰면서 팀원을 챙기고 이끄는 현장 리더형입니다. 사람과 일을 함께 굴리는 데 강하지만, 장기 계획이나 문서 정리는 의식적으로 시간을 떼어 챙겨야 합니다. 추천 직무: 현장·매장 관리자, 행사 운영 총괄, 스포츠 코치, 시설·물류 팀장.'),
('RIASEC-RSC','riasec','RSC (현실-사회-관습)','실물을 다루는 일(R)이 중심이고, 사람(S)과 체계(C)가 더해진 조합입니다. 정해진 절차를 지키면서 사람들이 안전하고 편하게 지내도록 돕는 일에 맞습니다. 믿고 맡길 수 있는 꾸준함이 강점이지만, 갑작스러운 변화에는 시간을 두고 적응하는 편입니다. 추천 직무: 시설·안전 관리, 보건·의료 지원, 물류 운영, 고객 현장 서비스.'),
('RIASEC-REI','riasec','REI (현실-기업-탐구)','손으로 하는 일(R)이 중심이고, 추진력(E)과 분석(I)이 더해진 조합입니다. 현장 감각을 바탕으로 문제를 분석하고, 해결책을 밀어붙여 성과로 만듭니다. 기술을 아는 리더로 신뢰를 얻지만, 결정의 이유를 팀원에게 충분히 설명하는 시간을 아끼지 않는 것이 중요합니다. 추천 직무: 생산·공정 관리자, 기술 영업, 엔지니어링 PM, 건설·설비 현장 관리.'),
('RIASEC-REA','riasec','REA (현실-기업-예술)','실물을 다루는 일(R)이 중심이고, 추진력(E)과 창의성(A)이 더해진 조합입니다. 새로운 것을 직접 만들고, 그것을 세상에 내놓는 데까지 밀어붙이는 힘이 있습니다. 실행이 앞서는 만큼 숫자와 일정 관리는 따로 체계를 세워 두면 오래 갑니다. 추천 직무: 제작사·스튜디오 운영, 브랜드 제품 개발, 공간 사업, 이벤트 프로덕션.'),
('RIASEC-RES','riasec','RES (현실-기업-사회)','손으로 하는 일(R)이 중심이고, 추진력(E)과 사람(S)이 더해진 조합입니다. 현장을 직접 챙기며 사람들을 모으고 움직이는 데 능합니다. 몸으로 보여 주는 리더십과 사람의 사정을 헤아리는 따뜻함이 함께 있지만, 모든 일을 혼자 떠안지 않도록 역할을 나누는 연습이 필요합니다. 추천 직무: 매장·지점 운영, 스포츠·레저 사업, 현장 서비스 관리, 행사 운영.'),
('RIASEC-REC','riasec','REC (현실-기업-관습)','실물을 다루는 일(R)이 중심이고, 추진력(E)과 체계(C)가 더해진 조합입니다. 현장을 정해진 기준대로 굴러가게 만들고, 목표 수치를 맞추는 데 강합니다. 효율과 규칙을 중시하는 만큼 새로운 시도에는 근거를 요구하는 편이라, 작은 실험부터 허용해 보면 시야가 넓어집니다. 추천 직무: 생산·물류 관리, 구매·자재 관리, 공정 관리, 시설 운영 책임자.'),
('RIASEC-RCI','riasec','RCI (현실-관습-탐구)','손으로 하는 일(R)이 중심이고, 체계(C)와 분석(I)이 더해진 조합입니다. 기준과 절차를 정확히 지키면서, 문제가 생기면 원인을 끝까지 찾아냅니다. 신뢰도 높은 결과를 내는 정밀형이지만, 완벽을 기하다 일정이 밀리지 않도록 마감 기준을 먼저 정해 두면 좋습니다. 추천 직무: 품질 보증, 시험·계측, 정비·유지보수, 데이터 센터·전산 운영.'),
('RIASEC-RCE','riasec','RCE (현실-관습-기업)','실물을 다루는 일(R)이 중심이고, 체계(C)와 추진력(E)이 더해진 조합입니다. 정해진 체계 안에서 일을 빈틈없이 처리하고, 성과로 이어지도록 관리합니다. 안정적인 운영을 맡기기 좋은 유형이며, 변화가 필요할 때는 근거를 갖고 설득받기를 원합니다. 추천 직무: 생산 관리, 물류·재고 관리, 시설 관리 책임자, 구매 관리.'),

-- ── I 탐구 중심 (16) ──
('RIASEC-IRA','riasec','IRA (탐구-현실-예술)','원리를 파고드는 탐구(I)가 중심이고, 손으로 만드는 일(R)과 창의성(A)이 더해진 조합입니다. 이론에 머물지 않고 직접 실험하고 만들어 보며 새로운 해법을 찾습니다. 호기심과 집중력이 깊지만, 관심 밖의 일에는 동기가 쉽게 떨어질 수 있어 일의 의미를 스스로 연결해 두는 것이 좋습니다. 추천 직무: 제품 연구개발, 하드웨어·로봇 엔지니어, 실험 설계, 인터랙션 디자인.'),
('RIASEC-IRS','riasec','IRS (탐구-현실-사회)','탐구(I)가 중심이고, 실무 기술(R)과 사람을 돕는 마음(S)이 더해진 조합입니다. 과학적 근거로 사람의 문제를 실질적으로 해결하는 일에 끌립니다. 정확하면서도 사람을 대하는 태도가 따뜻하지만, 근거가 부족한 상황에서 결정을 미루지 않도록 연습이 필요합니다. 추천 직무: 임상 연구, 의료·보건 전문직, 재활 공학, 환경·안전 연구.'),
('RIASEC-IRE','riasec','IRE (탐구-현실-기업)','탐구(I)가 중심이고, 실무 기술(R)과 추진력(E)이 더해진 조합입니다. 기술을 깊이 이해하고 그것을 실제 성과로 연결하려는 의지가 있습니다. 기술 기반 프로젝트를 끌고 가는 데 강하며, 전문 용어 없이 쉽게 설명하는 연습이 리더십을 키웁니다. 추천 직무: 기술 PM, R&D 리더, 기술 창업, 솔루션 엔지니어.'),
('RIASEC-IRC','riasec','IRC (탐구-현실-관습)','탐구(I)가 중심이고, 실무 기술(R)과 체계(C)가 더해진 조합입니다. 데이터와 장비를 다루며 정확한 결과를 내는 데 강합니다. 꼼꼼하고 검증을 중시하는 만큼, 빠른 결정이 필요한 상황에 대비해 판단 기준을 미리 정해 두면 좋습니다. 추천 직무: 데이터 엔지니어, 실험·분석 연구원, 품질 공학, 보안·시스템 엔지니어.'),
('RIASEC-IAR','riasec','IAR (탐구-예술-현실)','탐구(I)가 중심이고, 창의성(A)과 실무 기술(R)이 더해진 조합입니다. 분석으로 문제를 이해한 뒤 새로운 형태로 구현해 냅니다. 논리와 감각을 함께 쓰는 일에서 몰입하지만, 완성도를 높이느라 공유가 늦어지지 않도록 중간 결과를 자주 보여 주는 것이 좋습니다. 추천 직무: UX·제품 디자인, 크리에이티브 테크놀로지, 건축, 데이터 시각화.'),
('RIASEC-IAC','riasec','IAC (탐구-예술-관습)','탐구(I)가 중심이고, 창의성(A)과 체계(C)가 더해진 조합입니다. 깊이 분석하고 새롭게 해석하되, 결과는 정돈된 형태로 정리합니다. 복잡한 내용을 알기 쉽게 구조화하는 데 강하고, 혼자 몰입하는 시간이 충분할 때 가장 좋은 결과를 냅니다. 추천 직무: 리서치·인사이트 분석, 정보 디자인, 편집·출판 기획, 콘텐츠 전략.'),
('RIASEC-ISR','riasec','ISR (탐구-사회-현실)','탐구(I)가 중심이고, 사람을 돕는 마음(S)과 실무 기술(R)이 더해진 조합입니다. 사람에 대한 관심을 과학적 방법으로 풀어 내고, 연구가 실제 사람에게 쓰일 때 보람이 큽니다. 연구와 현장 사이를 오가는 역할에서 강점이 가장 잘 드러납니다. 추천 직무: 보건·의료 연구, 재활·작업 치료, 스포츠 과학, 환경 보건.'),
('RIASEC-ISA','riasec','ISA (탐구-사회-예술)','탐구(I)가 중심이고, 사람(S)과 표현(A)이 더해진 조합입니다. 사람의 마음과 행동을 깊이 이해하고, 그것을 이야기나 콘텐츠로 풀어 내는 데 끌립니다. 공감과 분석을 함께 갖췄지만, 다른 사람의 감정을 오래 붙들고 있지 않도록 스스로 쉬는 시간을 챙겨야 합니다. 추천 직무: 심리·상담 연구, UX 리서치, 교육 콘텐츠 개발, 소비자·트렌드 분석.'),
('RIASEC-ISE','riasec','ISE (탐구-사회-기업)','탐구(I)가 중심이고, 사람(S)과 리더십(E)이 더해진 조합입니다. 사람과 조직을 분석하고, 더 나은 방향으로 이끌고 싶어 합니다. 근거로 설득하는 힘이 있으며, 분석에서 멈추지 않고 실행 책임까지 맡을 때 영향력이 커집니다. 추천 직무: 조직·인사 컨설팅, 교육 기획, 정책 연구, 소비자 인사이트 리드.'),
('RIASEC-ISC','riasec','ISC (탐구-사회-관습)','탐구(I)가 중심이고, 사람(S)과 체계(C)가 더해진 조합입니다. 사람에 관한 데이터를 꼼꼼히 다루고, 정확한 근거로 돕는 일에 맞습니다. 신뢰받는 분석가형이지만, 숫자 뒤의 사람 이야기를 직접 듣는 기회를 만들면 분석이 더 깊어집니다. 추천 직무: 보건 통계, 인사 데이터 분석, 교육 평가, 사회 조사 연구.'),
('RIASEC-IER','riasec','IER (탐구-기업-현실)','탐구(I)가 중심이고, 리더십(E)과 실무 기술(R)이 더해진 조합입니다. 분석으로 기회를 찾고, 그것을 실제 제품이나 사업으로 밀어붙입니다. 기술 이해가 깊은 전략가형이며, 완벽한 근거를 기다리기보다 작게 시험해 보는 방식이 잘 맞습니다. 추천 직무: 기술 전략, 제품 관리(PM), 기술 컨설팅, 딥테크 창업.'),
('RIASEC-IEA','riasec','IEA (탐구-기업-예술)','탐구(I)가 중심이고, 리더십(E)과 창의성(A)이 더해진 조합입니다. 시장과 사람을 분석해 새로운 아이디어를 만들고 실행까지 이끕니다. 분석과 상상을 오가는 기획자형이며, 아이디어가 많을 때는 우선순위를 정하는 기준이 성과를 가릅니다. 추천 직무: 브랜드 전략, 신사업 기획, 마케팅 인사이트, 서비스 기획.'),
('RIASEC-IES','riasec','IES (탐구-기업-사회)','탐구(I)가 중심이고, 리더십(E)과 사람(S)이 더해진 조합입니다. 근거를 바탕으로 사람을 설득하고 조직을 움직이는 데 강합니다. 분석 결과를 사람이 받아들이게 만드는 소통력이 있으며, 상대의 입장을 먼저 묻는 습관이 설득력을 더 키웁니다. 추천 직무: 경영·조직 컨설팅, 교육 사업 기획, 정책 기획, 고객 경험(CX) 전략.'),
('RIASEC-IEC','riasec','IEC (탐구-기업-관습)','탐구(I)가 중심이고, 리더십(E)과 체계(C)가 더해진 조합입니다. 숫자와 근거로 판단하고, 그 판단을 체계적으로 실행합니다. 리스크를 미리 따지는 신중한 의사결정자형이지만, 지나친 검토로 기회를 놓치지 않도록 결정 시한을 정해 두면 좋습니다. 추천 직무: 재무 분석, 경영 전략, 리스크 관리, 투자 분석.'),
('RIASEC-ICR','riasec','ICR (탐구-관습-현실)','탐구(I)가 중심이고, 체계(C)와 실무 기술(R)이 더해진 조합입니다. 정확성과 검증을 가장 중시하며, 정밀한 작업에서 실력을 드러냅니다. 혼자 깊이 몰입할 때 성과가 크고, 결과를 다른 사람이 이해하기 쉽게 정리하는 습관이 평가를 높입니다. 추천 직무: 소프트웨어 테스트, 시스템 엔지니어, 실험 분석, 전산 감사.'),
('RIASEC-ICA','riasec','ICA (탐구-관습-예술)','탐구(I)가 중심이고, 체계(C)와 창의성(A)이 더해진 조합입니다. 복잡한 정보를 체계적으로 정리하고, 보기 좋게 전달하는 데 능합니다. 정확함과 감각을 함께 요구하는 일에서 강점이 드러나며, 세부에 빠질 때는 전체 목적을 한 번씩 돌아보면 좋습니다. 추천 직무: 데이터 시각화, 기술 문서 작성, 아카이브·자료 관리, 편집 기획.'),

-- ── A 예술 중심 (15) ──
('RIASEC-ARI','riasec','ARI (예술-현실-탐구)','새롭게 표현하는 창의성(A)이 중심이고, 손으로 만드는 일(R)과 탐구(I)가 더해진 조합입니다. 아이디어를 직접 만들어 보고, 재료와 기술을 연구하며 완성도를 높입니다. 작업에 깊이 몰입하는 장인형이며, 작업물을 꾸준히 기록하고 공개하면 기회가 넓어집니다. 추천 직무: 산업·제품 디자인, 영상·VFX 아티스트, 사운드 디자인, 공예 작가.'),
('RIASEC-ARS','riasec','ARS (예술-현실-사회)','창의성(A)이 중심이고, 손으로 만드는 일(R)과 사람(S)이 더해진 조합입니다. 직접 만든 작품이나 공간으로 사람들에게 감동과 쉼을 주고 싶어 합니다. 만드는 즐거움을 나누는 일에서 보람을 느끼며, 작업 시간을 지키기 위해 사람과의 약속을 조절하는 연습도 필요합니다. 추천 직무: 공예·미술 강사, 공간 스타일링, 무대·소품 디자인, 플로리스트.'),
('RIASEC-ARE','riasec','ARE (예술-현실-기업)','창의성(A)이 중심이고, 실무 기술(R)과 추진력(E)이 더해진 조합입니다. 새로운 작업을 직접 만들고, 그것을 사업이나 프로젝트로 키워 갑니다. 창작자이면서 제작자인 유형이며, 계약·정산 같은 관리 업무는 미루지 않도록 체계를 갖춰 두면 좋습니다. 추천 직무: 영상 감독·PD, 크리에이티브 스튜디오 운영, 패션·제품 브랜드 창업, 아트 디렉터.'),
('RIASEC-AIR','riasec','AIR (예술-탐구-현실)','창의성(A)이 중심이고, 탐구(I)와 실무 기술(R)이 더해진 조합입니다. 새로운 표현을 찾되, 원리를 이해하고 기술로 구현하는 데까지 갑니다. 기술과 예술의 경계에서 빛나는 유형이며, 혼자 완성하려 하기보다 다른 분야 사람과 협업할 때 결과가 커집니다. 추천 직무: 미디어 아트, 게임·인터랙션 디자인, 건축 디자인, 3D 아티스트.'),
('RIASEC-AIC','riasec','AIC (예술-탐구-관습)','창의성(A)이 중심이고, 탐구(I)와 체계(C)가 더해진 조합입니다. 독창적인 아이디어를 깊이 있게 다듬고, 정돈된 결과물로 완성합니다. 감각과 논리를 모두 요구하는 편집·설계 작업에 강하고, 완벽을 기하다 마감을 놓치지 않도록 단계별 기한을 두면 좋습니다. 추천 직무: 편집 디자인, UX 라이팅, 출판 기획, 브랜드 아이덴티티 디자인.'),
('RIASEC-ASR','riasec','ASR (예술-사회-현실)','창의성(A)이 중심이고, 사람(S)과 실무 기술(R)이 더해진 조합입니다. 사람들과 함께 무언가를 만들고 표현하는 활동에서 힘을 얻습니다. 체험과 참여를 이끄는 데 강하며, 내가 만든 프로그램의 효과를 기록해 두면 경력으로 쌓입니다. 추천 직무: 예술 교육, 문화 체험 프로그램, 공연 스태프, 공방 운영.'),
('RIASEC-ASI','riasec','ASI (예술-사회-탐구)','창의성(A)이 중심이고, 사람(S)과 탐구(I)가 더해진 조합입니다. 사람의 마음을 깊이 이해하고 그것을 표현으로 옮기는 데 끌립니다. 공감에서 출발한 창작이 강점이며, 감정 소모가 큰 주제를 다룰 때는 회복할 시간을 미리 확보해 두는 것이 좋습니다. 추천 직무: 작가·에디터, 예술 치료, 교육 콘텐츠 기획, 다큐멘터리 제작.'),
('RIASEC-ASC','riasec','ASC (예술-사회-관습)','창의성(A)이 중심이고, 사람(S)과 체계(C)가 더해진 조합입니다. 사람을 위한 콘텐츠를 만들되, 일정과 형식을 지켜 안정적으로 완성합니다. 창작과 운영을 함께 해낼 수 있는 유형이며, 반복 업무 속에서도 새로운 시도를 할 여지를 남겨 두면 동기가 유지됩니다. 추천 직무: 교육·출판 편집, 문화 프로그램 운영, 콘텐츠 매니저, 커뮤니티 콘텐츠 기획.'),
('RIASEC-AER','riasec','AER (예술-기업-현실)','창의성(A)이 중심이고, 추진력(E)과 실무 기술(R)이 더해진 조합입니다. 아이디어를 내는 데서 끝나지 않고 직접 만들어 시장에 내놓습니다. 창작과 사업 감각을 함께 가졌지만, 여러 일을 동시에 벌이기 쉬우니 끝낼 일을 먼저 정하는 습관이 중요합니다. 추천 직무: 크리에이티브 디렉터, 제작사 대표, 브랜드 디자이너, 영상 프로듀서.'),
('RIASEC-AEI','riasec','AEI (예술-기업-탐구)','창의성(A)이 중심이고, 추진력(E)과 탐구(I)가 더해진 조합입니다. 새로운 아이디어를 내고, 시장과 사람을 분석해 설득력 있게 밀고 나갑니다. 콘셉트를 세우는 데 강한 기획자형이며, 실행 단계의 세부는 꼼꼼한 동료와 나누면 완성도가 올라갑니다. 추천 직무: 광고 크리에이티브, 브랜드 기획, 콘텐츠 전략, 서비스 콘셉트 기획.'),
('RIASEC-AES','riasec','AES (예술-기업-사회)','창의성(A)이 중심이고, 추진력(E)과 사람(S)이 더해진 조합입니다. 사람들의 마음을 움직이는 표현으로 분위기를 만들고 이끄는 데 능합니다. 무대 위에서든 기획 자리에서든 사람을 모으는 힘이 있으며, 반응에 흔들리지 않도록 내 기준을 세워 두는 것이 좋습니다. 추천 직무: 공연·행사 기획, 크리에이터, 홍보·PR, 엔터테인먼트 기획.'),
('RIASEC-AEC','riasec','AEC (예술-기업-관습)','창의성(A)이 중심이고, 추진력(E)과 체계(C)가 더해진 조합입니다. 창의적인 아이디어를 실행 계획과 예산 안에서 현실로 만듭니다. 크리에이티브와 관리를 함께 잡는 유형이며, 관리 업무에 시간을 빼앗겨 창작이 줄지 않도록 균형을 챙겨야 합니다. 추천 직무: 광고 AE, 콘텐츠 프로듀서, 브랜드 매니저, 전시·행사 PM.'),
('RIASEC-ACI','riasec','ACI (예술-관습-탐구)','창의성(A)이 중심이고, 체계(C)와 탐구(I)가 더해진 조합입니다. 디테일을 세심히 다듬고, 근거를 갖춘 표현을 추구합니다. 완성도에 대한 기준이 높아 신뢰받지만, 스스로에게 지나치게 엄격하지 않도록 충분히 좋은 수준을 정해 두면 좋습니다. 추천 직무: 편집자, 타이포그래피·그래픽 디자인, 아카이브 큐레이터, UX 디자인.'),
('RIASEC-ACS','riasec','ACS (예술-관습-사회)','창의성(A)이 중심이고, 체계(C)와 사람(S)이 더해진 조합입니다. 사람들이 쓰기 편하고 보기 좋은 결과물을 꼼꼼하게 만듭니다. 사용자를 배려하는 섬세함이 강점이며, 내 의견을 분명히 말하는 연습이 결과물의 방향을 지키는 데 도움이 됩니다. 추천 직무: 교육 콘텐츠 디자인, 출판 편집, 서비스 디자인, 전시 코디네이터.'),
('RIASEC-ACE','riasec','ACE (예술-관습-기업)','창의성(A)이 중심이고, 체계(C)와 추진력(E)이 더해진 조합입니다. 창의적 결과물을 기준과 일정에 맞춰 내고, 성과로 연결합니다. 크리에이티브 조직을 안정적으로 운영하는 데 강하며, 정해진 틀이 새로운 시도를 막지 않는지 가끔 점검하면 좋습니다. 추천 직무: 디자인 매니저, 콘텐츠 운영 리드, 브랜드 매니저, 패션 MD.'),

-- ── S 사회 중심 (17) ──
('RIASEC-SRI','riasec','SRI (사회-현실-탐구)','사람을 돕고 가르치는 일(S)이 중심이고, 실무 기술(R)과 탐구(I)가 더해진 조합입니다. 사람의 몸과 생활을 실제로 돌보고, 근거 있는 방법으로 돕고 싶어 합니다. 현장에서 신뢰를 얻는 전문 돌봄형이며, 다른 사람을 챙기느라 자기 회복을 미루지 않는 것이 오래 가는 비결입니다. 추천 직무: 간호, 물리·작업 치료, 운동 처방, 보건 교육.'),
('RIASEC-SRA','riasec','SRA (사회-현실-예술)','사람(S)이 중심이고, 실무 기술(R)과 표현(A)이 더해진 조합입니다. 사람들과 함께 몸을 쓰고 만들며 즐거움을 나누는 활동에 끌립니다. 체험을 통해 가르치는 데 강하며, 내가 운영한 활동을 사진·기록으로 남겨 두면 다음 기회로 이어집니다. 추천 직무: 체육·레크리에이션 강사, 예술 체험 교육, 아동 교육, 치료 레크리에이션.'),
('RIASEC-SRE','riasec','SRE (사회-현실-기업)','사람(S)이 중심이고, 실무 기술(R)과 리더십(E)이 더해진 조합입니다. 현장에서 사람들을 직접 챙기고 이끄는 데 능합니다. 팀을 돌보는 리더로 신뢰받지만, 모두를 만족시키려다 결정이 늦어지지 않도록 우선순위를 분명히 하는 것이 좋습니다. 추천 직무: 스포츠 코치, 현장 서비스 매니저, 캠프·교육 운영, 시설 운영 책임자.'),
('RIASEC-SRC','riasec','SRC (사회-현실-관습)','사람(S)이 중심이고, 실무 기술(R)과 체계(C)가 더해진 조합입니다. 정해진 절차 안에서 사람들을 안전하고 꼼꼼하게 돌봅니다. 믿고 맡길 수 있는 꾸준함이 강점이며, 절차로 해결되지 않는 상황에서 유연하게 판단하는 경험을 쌓으면 좋습니다. 추천 직무: 보건·의료 지원, 돌봄 서비스 관리, 안전 교육, 고객 지원 운영.'),
('RIASEC-SIR','riasec','SIR (사회-탐구-현실)','사람(S)이 중심이고, 탐구(I)와 실무 기술(R)이 더해진 조합입니다. 사람을 돕는 일을 과학적 근거와 기술로 뒷받침합니다. 전문성으로 돌보는 유형이며, 자격과 전문 지식을 꾸준히 쌓을수록 선택지가 넓어집니다. 추천 직무: 의료 전문직, 재활 치료, 보건 연구, 영양 상담.'),
('RIASEC-SIA','riasec','SIA (사회-탐구-예술)','사람(S)이 중심이고, 탐구(I)와 표현(A)이 더해진 조합입니다. 사람의 마음을 깊이 이해하고 따뜻하게 표현하는 데 강합니다. 상담과 교육에서 자연스럽게 빛나며, 공감한 만큼 지치기 쉬우니 감정을 정리하는 자기만의 방법을 갖추는 것이 좋습니다. 추천 직무: 상담·심리 치료, 교육 콘텐츠 개발, 예술 치료, 커뮤니티 매니저.'),
('RIASEC-SIE','riasec','SIE (사회-탐구-기업)','사람(S)이 중심이고, 탐구(I)와 리더십(E)이 더해진 조합입니다. 사람과 조직의 문제를 분석하고, 더 나은 방향으로 이끌고 싶어 합니다. 성장을 돕는 리더형이며, 돕고 싶은 마음이 앞설 때 상대가 스스로 결정할 여지를 남겨 두면 효과가 큽니다. 추천 직무: HR·조직 개발, 교육 기획, 커리어 코칭, 사회 정책 기획.'),
('RIASEC-SIC','riasec','SIC (사회-탐구-관습)','사람(S)이 중심이고, 탐구(I)와 체계(C)가 더해진 조합입니다. 사람을 돕는 일을 정확한 기록과 근거로 체계화합니다. 신뢰할 수 있는 지원 체계를 만드는 데 강하며, 서류 업무에 묻혀 사람을 만나는 시간이 줄지 않도록 균형을 챙겨야 합니다. 추천 직무: 사회복지 행정, 상담 기록·평가, 교육 행정, 보건 관리.'),
('RIASEC-SAR','riasec','SAR (사회-예술-현실)','사람(S)이 중심이고, 표현(A)과 실무 기술(R)이 더해진 조합입니다. 사람들과 함께 만들고 표현하는 활동으로 즐거움과 치유를 줍니다. 참여형 프로그램을 이끄는 데 강하며, 프로그램을 체계적으로 정리해 두면 더 많은 사람에게 전할 수 있습니다. 추천 직무: 예술·공예 교육, 놀이·미술 치료, 문화 프로그램 운영, 유아 교육.'),
('RIASEC-SAI','riasec','SAI (사회-예술-탐구)','사람(S)이 중심이고, 표현(A)과 탐구(I)가 더해진 조합입니다. 사람을 이해하고 그 이해를 따뜻한 콘텐츠로 풀어 냅니다. 배움을 즐겁게 만드는 유형이며, 좋은 아이디어를 끝까지 완성하기 위해 마감을 스스로 정해 두는 것이 도움이 됩니다. 추천 직무: 교육 콘텐츠 기획, 상담, 작가·에디터, 교수 설계.'),
('RIASEC-SAC','riasec','SAC (사회-예술-관습)','사람(S)이 중심이고, 표현(A)과 체계(C)가 더해진 조합입니다. 사람을 위한 프로그램을 창의적으로 만들고 꼼꼼하게 운영합니다. 기획과 운영을 함께 해내는 유형이며, 맡은 일이 많아질 때 거절하는 연습이 번아웃을 막아 줍니다. 추천 직무: 교육 프로그램 운영, 문화·복지 프로그램 기획, 커뮤니티 운영, 행사 코디네이터.'),
('RIASEC-SER','riasec','SER (사회-기업-현실)','사람(S)이 중심이고, 리더십(E)과 실무 기술(R)이 더해진 조합입니다. 사람들을 모아 현장에서 직접 움직이게 하는 데 능합니다. 따뜻하면서도 실행력 있는 리더형이며, 성과를 숫자로 정리해 두면 내 기여를 더 잘 보여 줄 수 있습니다. 추천 직무: 스포츠·레저 운영, 현장 서비스 관리, 봉사·캠프 리더, 매장 매니저.'),
('RIASEC-SEI','riasec','SEI (사회-기업-탐구)','사람(S)이 중심이고, 리더십(E)과 탐구(I)가 더해진 조합입니다. 사람을 이해하고 근거를 갖고 조직을 이끌고 싶어 합니다. 사람 중심의 변화를 설계하는 데 강하며, 변화의 속도를 사람들이 따라올 수 있게 조절하는 감각이 중요합니다. 추천 직무: HR 리더, 교육 사업 기획, 조직 문화 담당, 사회 혁신 기획.'),
('RIASEC-SEC','riasec','SEC (사회-기업-관습)','사람(S)이 중심이고, 리더십(E)과 체계(C)가 더해진 조합입니다. 사람을 챙기면서도 일을 체계적으로 관리하는 균형형 리더입니다. 조직이 안정적으로 굴러가게 만들며, 익숙한 방식이 사람들의 새로운 시도를 막고 있지 않은지 가끔 돌아보면 좋습니다. 추천 직무: 인사 관리, 교육 운영 관리, 고객 서비스 매니저, 사회복지 기관 운영.'),
('RIASEC-SCR','riasec','SCR (사회-관습-현실)','사람(S)이 중심이고, 체계(C)와 실무 기술(R)이 더해진 조합입니다. 정해진 기준과 절차로 사람들을 성실하게 돕습니다. 현장 운영을 안정적으로 맡길 수 있는 유형이며, 개선 아이디어를 적극적으로 말할수록 역할이 커집니다. 추천 직무: 보건·의료 행정, 돌봄 서비스 운영, 고객 지원, 안전 관리.'),
('RIASEC-SCA','riasec','SCA (사회-관습-예술)','사람(S)이 중심이고, 체계(C)와 표현(A)이 더해진 조합입니다. 사람을 위한 일을 꼼꼼하게 정리하고 보기 좋게 전달합니다. 세심한 배려가 결과물에 드러나며, 뒤에서 받치는 역할에 머물지 않고 내 작업을 드러내는 연습도 필요합니다. 추천 직무: 교육 자료 개발, 고객 커뮤니케이션, 행정 지원, 커뮤니티 콘텐츠 운영.'),
('RIASEC-SCE','riasec','SCE (사회-관습-기업)','사람(S)이 중심이고, 체계(C)와 리더십(E)이 더해진 조합입니다. 사람을 위한 제도와 절차를 만들고 운영하는 데 강합니다. 공정하고 믿음직한 관리자형이며, 규정만큼 사람의 사정을 함께 살피는 지금의 강점을 리더 역할에서도 지켜 가면 좋습니다. 추천 직무: 인사·노무 관리, 교육 행정, 고객 서비스 관리, 공공 서비스 운영.'),

-- ── E 기업 중심 (15) ──
('RIASEC-ERI','riasec','ERI (기업-현실-탐구)','사람을 이끌고 설득하는 리더십(E)이 중심이고, 실무 기술(R)과 탐구(I)가 더해진 조합입니다. 기술을 이해하고 그것을 사업 성과로 밀어붙이는 데 강합니다. 현장을 아는 사업가형이며, 빠른 추진 속에서도 팀원의 의견을 들을 시간을 남겨 두면 실행력이 더 커집니다. 추천 직무: 기술 영업, 제조·생산 사업 관리, 엔지니어링 PM, 기술 창업.'),
('RIASEC-ERA','riasec','ERA (기업-현실-예술)','리더십(E)이 중심이고, 실무 기술(R)과 창의성(A)이 더해진 조합입니다. 새로운 제품이나 콘텐츠를 직접 만들어 시장에 내놓는 데 힘이 납니다. 만드는 일과 파는 일을 함께 챙기며, 일을 벌이는 속도만큼 마무리를 챙기는 장치를 두면 좋습니다. 추천 직무: 제작사·스튜디오 대표, 제품 브랜드 사업, 이벤트 프로덕션, 공간 사업.'),
('RIASEC-ERS','riasec','ERS (기업-현실-사회)','리더십(E)이 중심이고, 실무 기술(R)과 사람(S)이 더해진 조합입니다. 현장에서 사람들을 이끌며 목표를 달성합니다. 사람과 현장을 함께 챙기는 운영 리더형이며, 성과 압박이 클 때도 팀의 사정을 놓치지 않는 것이 지금의 강점을 지키는 길입니다. 추천 직무: 매장·지점 관리, 서비스 운영 총괄, 스포츠 사업, 프랜차이즈 운영.'),
('RIASEC-ERC','riasec','ERC (기업-현실-관습)','리더십(E)이 중심이고, 실무 기술(R)과 체계(C)가 더해진 조합입니다. 현장을 효율적으로 관리하며 목표 수치를 달성합니다. 운영 효율을 끌어올리는 관리자형이며, 효율만큼 사람들의 동기도 함께 살피면 성과가 오래 갑니다. 추천 직무: 생산·물류 관리, 구매 관리, 운영 매니저, 공급망 관리.'),
('RIASEC-EIR','riasec','EIR (기업-탐구-현실)','리더십(E)이 중심이고, 탐구(I)와 실무 기술(R)이 더해진 조합입니다. 분석에 기반해 기술 사업을 이끄는 전략가형입니다. 데이터와 현장 모두를 근거로 결정하며, 결정의 배경을 팀과 공유할수록 실행 속도가 빨라집니다. 추천 직무: 사업 개발, 기술 전략, 제품 리더, 기술 분야 투자 심사.'),
('RIASEC-EIA','riasec','EIA (기업-탐구-예술)','리더십(E)이 중심이고, 탐구(I)와 창의성(A)이 더해진 조합입니다. 시장을 분석하고 새로운 콘셉트로 판을 바꾸고 싶어 합니다. 전략과 상상을 함께 쓰는 기획 리더형이며, 큰 그림을 실행 단위로 나눠 줄 파트너가 있으면 성과가 커집니다. 추천 직무: 브랜드·마케팅 전략, 신사업 기획, 광고 기획, 서비스 기획 리드.'),
('RIASEC-EIS','riasec','EIS (기업-탐구-사회)','리더십(E)이 중심이고, 탐구(I)와 사람(S)이 더해진 조합입니다. 근거를 바탕으로 사람들을 설득하고 조직을 움직입니다. 사람과 데이터를 함께 보는 리더형이며, 설득보다 경청이 먼저일 때 신뢰가 더 깊어집니다. 추천 직무: 경영 컨설팅, HR 전략, 교육 사업 기획, 고객 성공 리드.'),
('RIASEC-EIC','riasec','EIC (기업-탐구-관습)','리더십(E)이 중심이고, 탐구(I)와 체계(C)가 더해진 조합입니다. 숫자와 분석으로 판단하고 체계적으로 실행합니다. 신중하면서도 결단력 있는 관리자형이며, 숫자로 드러나지 않는 사람의 변화에도 관심을 두면 판단이 더 정확해집니다. 추천 직무: 재무·투자 관리, 경영 기획, 리스크 관리, 사업 분석.'),
('RIASEC-EAR','riasec','EAR (기업-예술-현실)','리더십(E)이 중심이고, 창의성(A)과 실무 기술(R)이 더해진 조합입니다. 창의적인 아이디어를 실제 제품이나 콘텐츠로 만들어 시장에 내놓습니다. 실행력 있는 크리에이티브 사업가형이며, 숫자 관리를 맡아 줄 체계나 동료를 갖추면 안정적으로 성장합니다. 추천 직무: 콘텐츠 사업, 크리에이티브 에이전시 운영, 제품 브랜드 기획, 영상 프로듀서.'),
('RIASEC-EAC','riasec','EAC (기업-예술-관습)','리더십(E)이 중심이고, 창의성(A)과 체계(C)가 더해진 조합입니다. 새로운 아이디어를 계획과 예산 안에서 성과로 만듭니다. 크리에이티브를 관리하는 리더형이며, 관리 기준이 팀의 창의성을 누르지 않도록 실험할 여지를 열어 두면 좋습니다. 추천 직무: 마케팅 매니저, 광고 AE, 브랜드 매니저, 콘텐츠 사업 PM.'),
('RIASEC-ESR','riasec','ESR (기업-사회-현실)','리더십(E)이 중심이고, 사람(S)과 실무 기술(R)이 더해진 조합입니다. 사람들을 모으고 현장에서 함께 움직이게 하는 데 능합니다. 분위기를 만들고 결과를 내는 운영 리더형이며, 장기 계획을 세우는 시간을 따로 확보하면 한 단계 더 성장합니다. 추천 직무: 영업·서비스 팀장, 행사 운영, 스포츠·레저 사업, 매장 운영.'),
('RIASEC-ESI','riasec','ESI (기업-사회-탐구)','리더십(E)이 중심이고, 사람(S)과 탐구(I)가 더해진 조합입니다. 사람의 필요를 이해하고, 근거를 갖고 설득해 함께 움직입니다. 관계와 분석을 함께 쓰는 리더형이며, 많은 사람의 기대를 모두 떠안지 않도록 역할의 경계를 분명히 하면 좋습니다. 추천 직무: 영업 전략, HR 비즈니스 파트너, 고객 경험 관리, 교육 컨설팅.'),
('RIASEC-ESC','riasec','ESC (기업-사회-관습)','리더십(E)이 중심이고, 사람(S)과 체계(C)가 더해진 조합입니다. 사람을 챙기면서 일을 체계적으로 관리하는 조직 운영형입니다. 팀이 안정적으로 성과를 내게 만들며, 새로운 방식을 시도하는 구성원을 지지해 주면 조직이 함께 자랍니다. 추천 직무: 팀 관리자, 영업 관리, 인사 관리, 고객 서비스 총괄.'),
('RIASEC-ECR','riasec','ECR (기업-관습-현실)','리더십(E)이 중심이고, 체계(C)와 실무 기술(R)이 더해진 조합입니다. 체계와 현장 감각으로 운영 성과를 끌어올립니다. 효율을 중시하는 실무형 관리자이며, 변화가 필요한 시점을 놓치지 않도록 외부 흐름을 꾸준히 살피면 좋습니다. 추천 직무: 운영 관리, 생산·물류 관리, 구매·조달, 시설 관리 책임자.'),
('RIASEC-ECA','riasec','ECA (기업-관습-예술)','리더십(E)이 중심이고, 체계(C)와 창의성(A)이 더해진 조합입니다. 체계적인 관리 위에 새로운 시도를 얹어 성과를 냅니다. 안정과 변화를 함께 다루는 관리자형이며, 이 균형 감각이 조직의 신뢰를 얻는 가장 큰 무기입니다. 추천 직무: 브랜드 매니저, 마케팅 운영, 상품 기획(MD), 콘텐츠 사업 관리.'),

-- ── C 관습 중심 (16) ──
('RIASEC-CRI','riasec','CRI (관습-현실-탐구)','정해진 체계로 꼼꼼히 관리하는 일(C)이 중심이고, 실무 기술(R)과 탐구(I)가 더해진 조합입니다. 정확한 기준으로 데이터와 장비를 다루며, 오류를 찾아내는 데 강합니다. 정밀함이 필요한 일에서 신뢰받으며, 내가 찾은 개선점을 적극적으로 제안하면 역할이 넓어집니다. 추천 직무: 품질 관리, 데이터 관리, 회계·감사, 시스템 운영.'),
('RIASEC-CRS','riasec','CRS (관습-현실-사회)','체계(C)가 중심이고, 실무 기술(R)과 사람(S)이 더해진 조합입니다. 절차를 지키며 사람들이 불편 없이 지내도록 실무를 챙깁니다. 꾸준하고 성실한 운영자형이며, 보이지 않는 곳에서 한 일을 기록해 두면 기여가 제대로 평가받습니다. 추천 직무: 총무·시설 관리, 의료 행정, 고객 지원 운영, 물류 관리.'),
('RIASEC-CRE','riasec','CRE (관습-현실-기업)','체계(C)가 중심이고, 실무 기술(R)과 리더십(E)이 더해진 조합입니다. 정해진 기준대로 현장을 운영하고 목표를 맞춥니다. 효율적인 운영 관리자형이며, 기준에 맞지 않는 새로운 제안도 일단 들어 보는 여유가 팀의 성장을 돕습니다. 추천 직무: 생산·재고 관리, 구매 관리, 운영 관리, 공정 관리.'),
('RIASEC-CIR','riasec','CIR (관습-탐구-현실)','체계(C)가 중심이고, 탐구(I)와 실무 기술(R)이 더해진 조합입니다. 데이터와 시스템을 정확하게 다루고 검증합니다. 정밀성과 일관성이 가장 큰 강점이며, 결과를 짧고 쉽게 요약하는 연습이 영향력을 키웁니다. 추천 직무: 데이터 분석, 회계·세무, 시스템 관리, 품질 보증.'),
('RIASEC-CIA','riasec','CIA (관습-탐구-예술)','체계(C)가 중심이고, 탐구(I)와 창의성(A)이 더해진 조합입니다. 정보를 체계적으로 정리하고 보기 좋게 전달합니다. 복잡한 것을 질서 있게 만드는 데 강하며, 정리 방식에 나만의 시각을 더할 때 차별화됩니다. 추천 직무: 정보 관리, 편집·교정, 데이터 시각화, 아카이브 관리.'),
('RIASEC-CIS','riasec','CIS (관습-탐구-사회)','체계(C)가 중심이고, 탐구(I)와 사람(S)이 더해진 조합입니다. 정확한 정보와 분석으로 사람들을 돕습니다. 신뢰받는 지원 전문가형이며, 데이터 뒤의 사람을 직접 만나는 경험이 분석을 더 의미 있게 만듭니다. 추천 직무: 인사 데이터 관리, 보건 행정, 교육 평가, 사회 조사.'),
('RIASEC-CIE','riasec','CIE (관습-탐구-기업)','체계(C)가 중심이고, 탐구(I)와 리더십(E)이 더해진 조합입니다. 분석과 체계로 조직의 의사결정을 뒷받침합니다. 숫자로 말하는 관리자형이며, 리스크만큼 기회도 함께 짚어 주면 의사결정자에게 더 큰 신뢰를 얻습니다. 추천 직무: 재무·회계 관리, 경영 기획, 리스크 관리, 내부 감사.'),
('RIASEC-CAI','riasec','CAI (관습-예술-탐구)','체계(C)가 중심이고, 창의성(A)과 탐구(I)가 더해진 조합입니다. 꼼꼼함 위에 감각과 깊이를 더해 완성도 높은 결과물을 만듭니다. 디테일을 놓치지 않는 유형이며, 세부 검토에 앞서 전체 방향을 먼저 합의하면 수정이 줄어듭니다. 추천 직무: 편집자, 기술 문서 작성, 디자인 QA, 콘텐츠 관리.'),
('RIASEC-CAS','riasec','CAS (관습-예술-사회)','체계(C)가 중심이고, 창의성(A)과 사람(S)이 더해진 조합입니다. 사람을 위한 자료와 프로그램을 정돈되게 만들고 운영합니다. 세심하고 친절한 운영자형이며, 반복 업무 속에서 작은 개선을 시도하는 습관이 성장의 발판이 됩니다. 추천 직무: 교육 운영, 고객 커뮤니케이션, 행사 코디네이터, 출판 편집.'),
('RIASEC-CAE','riasec','CAE (관습-예술-기업)','체계(C)가 중심이고, 창의성(A)과 리더십(E)이 더해진 조합입니다. 체계적인 관리 속에서 새로운 아이디어를 실행으로 연결합니다. 크리에이티브 프로젝트를 안정적으로 끌고 가는 유형이며, 일정이 빠듯할수록 품질 기준을 먼저 합의해 두면 좋습니다. 추천 직무: 프로젝트 매니저, 마케팅 운영, 상품 관리(MD), 광고 운영.'),
('RIASEC-CSR','riasec','CSR (관습-사회-현실)','체계(C)가 중심이고, 사람(S)과 실무 기술(R)이 더해진 조합입니다. 정해진 절차로 사람들을 성실하게 지원합니다. 조직의 기반을 단단히 받치는 유형이며, 맡은 일이 늘어날 때 우선순위를 상사와 미리 맞춰 두면 부담이 줄어듭니다. 추천 직무: 총무·행정, 의료 행정, 고객 지원, 시설 운영.'),
('RIASEC-CSI','riasec','CSI (관습-사회-탐구)','체계(C)가 중심이고, 사람(S)과 탐구(I)가 더해진 조합입니다. 사람에 관한 정보를 정확하게 다루고 분석합니다. 공정하고 꼼꼼한 지원 전문가형이며, 개인정보처럼 민감한 정보를 다루는 일에서 특히 신뢰를 얻습니다. 추천 직무: 인사 관리, 교육 행정, 상담 기록·평가, 사회복지 행정.'),
('RIASEC-CSA','riasec','CSA (관습-사회-예술)','체계(C)가 중심이고, 사람(S)과 표현(A)이 더해진 조합입니다. 사람을 위한 일을 꼼꼼하게 챙기고 따뜻하게 전달합니다. 세심한 배려가 강점이며, 내 생각을 먼저 꺼내는 연습을 하면 조율자에서 기획자로 역할이 넓어집니다. 추천 직무: 교육 지원, 고객 커뮤니케이션, 행정 지원, 커뮤니티 운영.'),
('RIASEC-CSE','riasec','CSE (관습-사회-기업)','체계(C)가 중심이고, 사람(S)과 리더십(E)이 더해진 조합입니다. 사람을 위한 제도와 절차를 공정하게 운영합니다. 믿음직한 조직 관리자형이며, 규정의 취지를 설명해 주는 습관이 구성원의 납득을 이끌어 냅니다. 추천 직무: 인사·총무 관리, 고객 서비스 관리, 교육 행정 관리, 공공 행정.'),
('RIASEC-CER','riasec','CER (관습-기업-현실)','체계(C)가 중심이고, 리더십(E)과 실무 기술(R)이 더해진 조합입니다. 체계적인 관리와 현장 감각으로 운영을 효율화합니다. 안정적인 운영 책임자형이며, 현장의 목소리를 정기적으로 듣는 자리를 만들면 개선이 더 정확해집니다. 추천 직무: 운영 관리, 재고·물류 관리, 구매 관리, 생산 관리.'),
('RIASEC-CEA','riasec','CEA (관습-기업-예술)','체계(C)가 중심이고, 리더십(E)과 창의성(A)이 더해진 조합입니다. 정해진 틀 안에서 새로운 방식을 시도해 성과를 냅니다. 관리와 변화를 균형 있게 다루는 유형이며, 작은 실험의 결과를 숫자로 보여 주면 더 큰 변화를 이끌 수 있습니다. 추천 직무: 마케팅 관리, 브랜드 운영, 상품 기획(MD), 프로젝트 관리.')
ON CONFLICT (id) DO NOTHING;
